class TTLCache:
    def __init__(self, clock):
        self.clock = clock
        self.entries = {}
    def put(self, key, value, ttl):
        self.entries[key] = (value, ttl)
    def get(self, key, default=None):
        if key not in self.entries:
            return default
        value, expiry = self.entries[key]
        if self.clock() > expiry:
            del self.entries[key]
            return default
        return value

